/* ===== Software testing · 2. isolation and test doubles ===== */
function sDbIsoT() {
  return CW('tst-db-isolation', {
    code: ["insert into users (email) values ('a@x.io')", "select count(*) … where email = 'a@x.io'", ['-- 200번 반복: 매번 1이어야 해요', '-- 200 times: must be 1 every time'], 'BEGIN … ROLLBACK', 'CREATE DATABASE t TEMPLATE ttbase'],
    hl: [[0, 3, 'accent'], [3, 1, 'ok'], [4, 1, 'warn']],
    draw: (S) => {
      rbars(S, 'b1', .5, [[['메모리 가짜', 'fake (Map)'], .05, 'ok', '0.002 ms'], [['PG 롤백', 'PG rollback'], .21, 'ok', '0.41 ms'], [['PG TRUNCATE', 'PG truncate'], .6, 'warn', '6.46 ms'], [['SQLite 새로', 'sql.js new'], .76, 'warn', '8.2 ms'], [['PG 템플릿', 'PG template'], 5.0, 'danger', '54.3 ms']], 1);
      lbl(S, 'l1', 19.0, 3.4, ['테스트 하나의 격리 비용이에요 · 트랜잭션을 롤백하면 진짜 PostgreSQL이 0.41ms였어요', 'isolation cost per test: rolling back a transaction took 0.41 ms on real PostgreSQL'], 'g', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.8, ['격리하지 않자 같은 테스트가 5번 중 4번 고유 제약에 걸려 실패했어요', 'without isolation, the same test failed 4 of 5 runs on a unique constraint'], 'r', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.2, ['템플릿 복제는 누가 원본에 붙어 있으면 거절됐어요', 'template cloning was refused while anyone was connected to the source'], 'w', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['가짜는 빠르지만 진짜 DB의 제약과 SQL을 확인하지 못해요', 'fakes are fast but never check real constraints and SQL'], 'a', 4, { w: 16.0 });
    },
    notes: [['DB를 쓰는 테스트는 앞 테스트가 남긴 데이터 때문에 결과가 달라지지 않게 격리해야 해요 · 같은 이메일로 사용자를 넣고 그 이메일의 수가 1인지 확인하는 테스트를 200번 돌렸어요 · 격리하지 않자 첫 번째만 통과하고 나머지는 고유 제약에 걸렸어요 · 다섯 번 중 네 번 실패예요', 'tests using a database must be isolated so data left by earlier tests cannot change results, so a test inserting a user with a fixed email and checking that exactly one exists was run repeatedly, and without isolation only the first run passed while the rest hit the unique constraint, four failures in five runs'], ['격리 방법별로 테스트 하나의 비용을 쟀어요 · 메모리의 Map으로 만든 가짜 저장소는 0.002ms였어요 · 진짜 PostgreSQL에서 테스트를 트랜잭션 안에서 실행하고 끝나면 ROLLBACK하자 0.41ms였어요 · 넣은 것이 커밋되지 않으니 다음 테스트는 깨끗한 상태를 봐요', 'the cost per test was measured by isolation method: a fake repository built on an in-memory Map took 0.002 ms, while running each test inside a transaction on real PostgreSQL and rolling back at the end took 0.41 ms, nothing being committed so the next test sees a clean state'], ['테이블을 TRUNCATE하고 시드 200행을 다시 넣으면 6.46ms, WASM SQLite인 sql.js로 매번 새 DB를 만들고 스키마와 시드를 넣으면 8.2ms였어요 · 템플릿 DB를 복제해 테스트마다 새 DB를 만들면 54.3ms였고, 원본 DB에 다른 연결이 붙어 있으면 복제가 거절됐어요', 'truncating tables and reinserting 200 seed rows took 6.46 ms, creating a fresh database with sql.js, a WASM SQLite, then adding schema and seeds took 8.2 ms, and cloning a template database per test took 54.3 ms, the clone being refused whenever another connection was attached to the source'], ['롤백 방식은 빠르고 진짜 DB를 쓰지만, 테스트 대상이 스스로 커밋하거나 여러 연결을 쓰면 쓸 수 없어요 · 그때는 TRUNCATE나 DB 복제를 써요 · 메모리 가짜는 가장 빠르지만 고유 제약, 외래 키, SQL 문법 오류를 확인하지 못하므로, 저장소 계층의 테스트는 진짜 DB로 해요', 'rollback is fast and uses the real database but cannot be used when the code under test commits on its own or uses several connections, where truncation or database cloning take over, and in-memory fakes, though fastest, never check unique constraints, foreign keys or SQL syntax errors, so repository-layer tests run against a real database']],
    fin: [['롤백으로 0.41ms', '0.41 ms with rollback', 'swt-xs swt-a'], ['격리 없으면 4/5 실패', 'no isolation: 4 of 5 fail'], ['가짜는 SQL을 몰라요', 'fakes do not know SQL']],
    caps: [['남은 데이터', 'Leftover data'], ['트랜잭션 롤백', 'Transaction rollback'], ['다른 방법들', 'Other methods'], ['무엇을 고를까', 'What to choose'], ['DB 격리', 'Database isolation']]
  });
}

function sMockFakeT() {
  return CW('tst-mock-fake', {
    code: ['// v1: findByEmail → insert', '// v2: insertIfAbsent (same behavior)', 'expect(repo.insert).toHaveBeenCalledWith(…)', ['// 목: 어떤 메서드를 불렀는지 확인', '// mock: checks which methods were called'], ['// 가짜: 저장된 결과를 확인', '// fake: checks the stored result']],
    hl: [[0, 2, 'accent'], [2, 2, 'warn'], [4, 1, 'ok']],
    draw: (S) => {
      mono(S, 'm1', 19.0, .5, nbs([['             v1     v2', '             v1     v2'], ['목 테스트    5/5    0/5', 'mock tests   5/5    0/5'], ['가짜 테스트  5/5    5/5', 'fake tests   5/5    5/5']]), 1, { w: 12.4, dy: .55, c: 'swt-g' });
      lbl(S, 'l1', 19.0, 2.3, ['동작이 같은 리팩터링인데 호출을 확인하는 목 테스트는 5개 모두 깨졌어요', 'a behavior-preserving refactor broke all 5 mock tests that verify calls'], 'r', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 3.7, ['결과 상태를 확인하는 가짜 저장소 테스트는 5개 모두 그대로 통과했어요', 'all 5 fake-repository tests checking resulting state still passed'], 'g', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.1, ['게다가 v2는 확인 후 넣기 사이의 경쟁을 없앤 더 나은 코드였어요', 'v2 was even better code, removing the race between check and insert'], 'a', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 6.5, ['목은 결제나 메일처럼 밖으로 나가는 부수 효과를 확인할 때 써요', 'use mocks to verify outgoing side effects such as payments or email'], 'w', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['테스트는 어떻게가 아니라 무엇을 확인해야 해요', 'tests should check what happened, not how'], 'a', 4, { w: 16.0 });
    },
    notes: [['회원 가입 서비스 v1은 저장소의 findByEmail로 이미 있는지 확인한 뒤 insert로 넣어요 · v2는 insertIfAbsent 하나로 바꿨어요 · 이미 있으면 거절하고, 이메일을 소문자로 바꾸고, id를 돌려주는 동작은 똑같아요', 'version 1 of a sign-up service checks with the repository’s findByEmail whether the email exists and then calls insert, while version 2 switched to a single insertIfAbsent, behaving identically by rejecting duplicates, lowercasing emails and returning the id'], ['목으로 만든 테스트 5개는 findByEmail이 어떤 인자로 불렸는지, insert가 불렸는지를 확인해요 · v1에서는 5개 모두 통과했지만 v2에서는 5개 모두 실패했어요 · 동작은 같은데 내부에서 부르는 메서드가 바뀌었기 때문이에요', 'five mock-based tests verify which arguments findByEmail received and whether insert was called, all passing against v1 but all failing against v2, because although behavior was unchanged, the methods called internally had changed'], ['메모리에 데이터를 들고 있는 가짜 저장소로 만든 테스트 5개는 가입 뒤 저장된 사용자, 중복일 때 하나만 남는지, 이메일이 소문자로 저장됐는지를 확인해요 · v1과 v2 모두 5개 모두 통과했어요 · 결과 상태를 확인하므로 구현이 바뀌어도 깨지지 않아요', 'five tests built on a fake repository holding data in memory check the stored user after sign-up, that only one remains on duplicates and that the email was stored lowercased, all passing for both v1 and v2, since checking resulting state survives implementation changes'], ['v2는 확인과 넣기 사이에 다른 요청이 끼어드는 경쟁을 없앤 더 나은 코드였는데, 목 테스트는 이 개선을 막는 쪽으로 작동했어요 · 목은 결제 요청, 메일 발송처럼 밖으로 나가 결과를 직접 볼 수 없는 부수 효과를 확인할 때 쓰고, 나머지는 가짜나 진짜 객체로 결과를 확인해요', 'v2 was better code, removing the race where another request slips in between the check and the insert, yet the mock tests worked against this improvement, so mocks are best reserved for outgoing side effects whose results cannot be observed directly, such as payment requests or sending email, with fakes or real objects checking results elsewhere']],
    fin: [['목 5개가 모두 깨졌어요', 'all 5 mock tests broke', 'swt-xs swt-a'], ['가짜는 그대로 통과', 'fakes kept passing'], ['결과를 확인해요', 'check outcomes']],
    caps: [['같은 동작의 리팩터링', 'A behavior-preserving refactor'], ['호출 확인', 'Verifying calls'], ['상태 확인', 'Checking state'], ['목을 쓸 곳', 'Where mocks belong'], ['목과 가짜', 'Mocks and fakes']]
  });
}

function sFakeTimerT() {
  return CW('tst-fake-timers', {
    code: ['withRetry(fn, delays = [200, 400, 800])', 'vi.useFakeTimers()', 'const p = withRetry(flaky)', 'await vi.advanceTimersByTimeAsync(1399)', ['expect(calls).toBe(3)   // 1,400ms에 4번째', 'expect(calls).toBe(3)   // 4th at 1,400 ms']],
    hl: [[0, 1, 'ink-3'], [1, 4, 'ok']],
    draw: (S) => {
      rbars(S, 'b1', .5, [[['진짜 타이머', 'real timers'], 5.0, 'warn', '14.19 s'], [['가짜 타이머', 'fake timers'], .06, 'ok', '0.16 s']], 1);
      lbl(S, 'l1', 19.0, 1.75, ['재시도를 기다리는 테스트 10개가 14.19초에서 0.164초로 줄었어요', '10 tests waiting on retries went from 14.19 s to 0.164 s'], 'g', 1, { w: 12.4 });
      mono(S, 'm2', 19.0, 3.15, nbs([['1,399ms: 호출 3번', '1,399 ms: 3 calls'], ['1,400ms: 호출 4번 → 실패', '1,400 ms: 4 calls → rejects']]), 2, { w: 12.4, dy: .55, c: 'swt-g' });
      lbl(S, 'l2', 19.0, 4.35, ['시간을 직접 넘기니 1ms 단위로 정확히 확인할 수 있었어요', 'advancing time by hand allowed checks accurate to 1 ms'], 'a', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.75, ['진짜 시간에 기대면 느린 CI에서는 타이밍이 어긋나 불안정해져요', 'relying on real time makes tests flaky on slow CI machines'], 'w', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['테스트가 끝나면 진짜 타이머로 되돌려요', 'restore real timers after each test'], 'a', 4, { w: 16.0 });
    },
    notes: [['withRetry는 실패하면 200ms, 400ms, 800ms를 기다리며 세 번 다시 시도해요 · 네 번째에 성공하는 경우를 확인하는 테스트 10개를 진짜 타이머로 돌리자 테스트마다 1.4초씩, 모두 14.19초가 걸렸어요 · 기다리는 시간이 곧 테스트 시간이 돼요', 'withRetry retries three times on failure, waiting 200, 400 and 800 ms, and ten tests checking success on the fourth try took 1.4 seconds each with real timers, 14.19 seconds in all, the waiting time becoming test time'], ['Vitest의 가짜 타이머를 켜면 setTimeout이 진짜 시간 대신 테스트가 넘겨 주는 가짜 시계를 따라요 · advanceTimersByTimeAsync로 1,400ms를 넘기자 같은 10개에 한 개를 더한 11개가 0.164초에 끝났어요 · 86배 빨라졌어요', 'with Vitest’s fake timers, setTimeout follows a fake clock advanced by the test instead of real time, and advancing 1,400 ms with advanceTimersByTimeAsync finished the same 10 tests plus one more, 11 in all, in 0.164 seconds, 86 times faster'], ['시간을 직접 넘기므로 정확한 시점도 확인할 수 있어요 · 계속 실패하는 경우를 테스트하며 1,399ms까지 넘기자 호출은 3번이었고, 1ms를 더 넘기자 4번째 호출이 일어나 마지막 오류가 나왔어요 · 진짜 시간으로는 이런 경계를 안정적으로 확인할 수 없어요', 'advancing time by hand also allows checking exact moments: testing permanent failure, advancing to 1,399 ms showed 3 calls, and one more millisecond triggered the 4th call and the final error, a boundary impossible to check reliably with real time'], ['진짜 시간에 기대는 테스트는 느리기만 한 것이 아니라, CI가 바쁠 때 타이머가 늦게 불려 불안정해져요 · 시간, 타이머, 날짜는 가짜 시계로 다루고, 테스트가 끝나면 진짜 타이머로 되돌려 다른 테스트에 새지 않게 해요', 'tests relying on real time are not just slow but turn flaky when timers fire late on busy CI machines, so time, timers and dates are handled with fake clocks, restoring real timers after each test so nothing leaks into other tests']],
    fin: [['시간을 직접 넘겨요', 'advance time by hand', 'swt-xs swt-a'], ['14초 → 0.16초', '14 s → 0.16 s'], ['1ms 단위로 정확히', 'accurate to 1 ms']],
    caps: [['기다리는 테스트', 'Tests that wait'], ['가짜 시계', 'A fake clock'], ['정확한 시점', 'Exact moments'], ['불안정함 줄이기', 'Reducing flakiness'], ['가짜 타이머', 'Fake timers']]
  });
}

