function sOrderT() {
  return CW('tst-order', {
    code: ['#2:  db.add("user-1")', '#3:  expect(db.has("user-1")).toBe(true)', '#7:  expect(fmt(1000))   // assumes KRW', '#13: cfg.currency = "USD"  // never restored', ['// 선언된 순서로는 모두 통과', '// all pass in declared order']],
    hl: [[0, 2, 'warn'], [2, 2, 'warn'], [4, 1, 'ok']],
    draw: (S) => {
      rbars(S, 'b1', .5, [[['선언 순서', 'declared'], .05, 'ok', '0 / 1'], [['섞은 순서', 'shuffled'], 3.78, 'danger', '756 / 1000']], 1);
      lbl(S, 'l1', 19.0, 1.75, ['테스트 20개의 순서를 1,000번 섞자 756번은 하나 이상 실패했어요', 'shuffling 20 tests 1,000 times gave at least one failure in 756 runs'], 'r', 1, { w: 12.4 });
      mono(S, 'm2', 19.0, 3.15, nbs([['#3 실패 490번: #2보다 먼저 실행', '#3 failed 490×: ran before #2'], ['#7 실패 506번: #13 뒤에 실행', '#7 failed 506×: ran after #13']]), 2, { w: 12.4, dy: .55, c: 'swt-r' });
      lbl(S, 'l2', 19.0, 4.35, ['다른 테스트가 만든 데이터에 기대거나, 바꾼 설정을 되돌리지 않은 테스트였어요', 'one test relied on another’s data; another changed config without restoring it'], 'w', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.75, ['파일을 나누거나 일부만 실행하면 순서가 바뀌어 그때 처음 드러나요', 'splitting files or running a subset changes order and exposes it then'], 'a', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['순서를 섞어 돌려 보면 숨은 의존이 드러나요', 'shuffling the order reveals hidden dependencies'], 'g', 4, { w: 16.0 });
    },
    notes: [['테스트 20개 가운데 두 쌍에 숨은 의존을 넣었어요 · 3번은 2번이 만든 user-1이 있다고 가정하고, 7번은 통화가 기본값인 원화라고 가정해요 · 13번은 통화를 USD로 바꾸고 되돌리지 않아요 · 선언된 순서로 돌리면 2번이 3번보다, 7번이 13번보다 먼저라서 모두 통과해요', 'hidden dependencies were planted in two pairs among 20 tests: test 3 assumes user-1 created by test 2 exists, test 7 assumes the currency is the default KRW, and test 13 switches the currency to USD without restoring it, so in declared order, with 2 before 3 and 7 before 13, everything passes'], ['순서를 무작위로 섞어 1,000번 돌리자 756번은 하나 이상의 테스트가 실패했어요 · 3번은 2번보다 먼저 실행된 490번에서, 7번은 13번 뒤에 실행된 506번에서 실패했어요 · 각각 절반 정도의 확률이고, 둘 중 하나라도 걸릴 확률은 4분의 3이에요', 'running 1,000 random orders, 756 had at least one failing test: test 3 failed in the 490 runs where it ran before test 2, and test 7 in the 506 where it ran after test 13, each roughly half the time, with about three in four runs hitting at least one'], ['이런 의존은 평소에는 보이지 않다가, 테스트를 여러 파일로 나누거나, 실패한 테스트 하나만 다시 돌리거나, 병렬 워커에 나눠 돌릴 때 처음 드러나요 · 그러면 그 테스트가 혼자서는 통과하는데 전체에서는 실패하는 이상한 일이 생겨요', 'such dependencies stay invisible until tests are split into files, a single failing test is rerun alone or tests are spread across parallel workers, producing the puzzling case of a test that passes alone but fails in the full run, or the reverse'], ['테스트는 필요한 데이터를 스스로 만들고, 바꾼 전역 상태는 끝날 때 되돌려야 해요 · Vitest의 sequence.shuffle처럼 순서를 섞어 돌리는 옵션을 CI에서 가끔 켜면 숨은 의존을 일찍 찾을 수 있어요 · 실패한 순서의 시드를 기록해 두면 재현할 수 있어요', 'tests should create the data they need and restore any global state they change, and occasionally enabling order shuffling in CI, such as Vitest’s sequence.shuffle, finds hidden dependencies early, with the seed of a failing order recorded so it can be reproduced']],
    fin: [['순서에 기대는 테스트', 'order-dependent tests', 'swt-xs swt-a'], ['섞으면 75.6% 실패', '75.6% fail when shuffled'], ['스스로 준비하고 되돌려요', 'set up and restore']],
    caps: [['숨은 의존', 'Hidden dependencies'], ['섞은 순서', 'Shuffled orders'], ['언제 드러날까', 'When it surfaces'], ['독립된 테스트', 'Independent tests'], ['테스트 순서', 'Test order']]
  });
}

