/* ===== Software testing · 3. flaky tests ===== */
function sSleepT() {
  return CW('tst-sleep-wait', {
    code: ['startJob()            // 25–45 ms of CPU', 'await sleep(80)', 'expect(job.done).toBe(true)', ['// 대신: 조건이 될 때까지 5ms마다 확인', '// instead: poll every 5 ms until true'], 'await waitFor(() => job.done, 2000)'],
    hl: [[0, 3, 'warn'], [3, 2, 'ok']],
    draw: (S) => {
      mono(S, 'm1', 19.0, .5, nbs([['             실패     평균', '             fails    avg'], ['한가할 때', 'idle'], '  sleep 80   0/200   80.3 ms', '  waitFor    0/200   41.4 ms', ['CPU 바쁠 때', 'CPU busy'], '  sleep 80 121/200   82.6 ms', '  waitFor    0/200   91.9 ms']), 1, { w: 12.4, dy: .55, c: 'swt-g' });
      lbl(S, 'l1', 19.0, 4.5, ['CPU를 다른 프로세스가 차지하자 80ms 고정 대기는 60.5%가 실패했어요', 'with other processes hogging the CPU, the fixed 80 ms sleep failed 60.5%'], 'r', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 5.9, ['조건을 확인하며 기다리면 늘 통과했고, 한가할 때는 오히려 더 빨랐어요', 'polling for the condition always passed and was even faster when idle'], 'g', 2, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['시간이 아니라 조건을 기다려요', 'wait for conditions, not for time'], 'g', 3, { w: 16.0 });
    },
    notes: [['비동기 작업이 끝났는지 확인하려고 정해진 시간만큼 sleep하는 테스트가 흔해요 · 25에서 45ms의 CPU 일을 하는 작업을 시작하고 80ms를 기다린 뒤 끝났는지 확인했어요 · 한가할 때는 200번 모두 통과했어요 · 넉넉해 보이는 여유예요', 'tests that sleep for a fixed time to see whether asynchronous work finished are common, so a job doing 25 to 45 ms of CPU work was started, the test waited 80 ms and then checked it was done, passing all 200 times when the machine was idle, an apparently generous margin'], ['같은 테스트를 2코어 컴퓨터에서 CPU를 독차지하는 프로세스 4개와 함께 돌렸어요 · CI 서버에서 여러 작업이 동시에 돌 때와 비슷한 상황이에요 · 작업이 CPU를 덜 받아 늦게 끝나면서 80ms 대기는 200번 중 121번, 60.5%가 실패했어요', 'the same test ran on a 2-core machine alongside four processes monopolizing the CPU, similar to a CI server running many jobs at once, and with the job getting less CPU and finishing later, the 80 ms wait failed 121 of 200 times, 60.5%'], ['조건이 참이 될 때까지 5ms마다 확인하고 2초를 상한으로 두는 waitFor로 바꾸자, 바쁠 때도 200번 모두 통과했어요 · 평균 대기는 91.9ms였어요 · 한가할 때는 41.4ms로, 80ms를 무조건 기다리는 것보다 오히려 빨랐어요', 'switching to waitFor, which checks every 5 ms until the condition holds with a 2-second cap, passed all 200 times even when busy, averaging 91.9 ms, while when idle it averaged 41.4 ms, faster than unconditionally waiting 80 ms'], ['고정 대기는 느린 환경에서는 실패하고 빠른 환경에서는 시간을 낭비해요 · 그래서 끝났다는 조건, 곧 상태, 이벤트, 화면의 요소를 기다려요 · 테스트 프레임워크의 waitFor나 Playwright의 자동 기다림이 이 일을 해요 · 상한 시간은 넉넉히 두되 그 시간을 늘 다 쓰지는 않아요', 'fixed waits fail in slow environments and waste time in fast ones, so tests wait for the condition of being done, a state, an event or an element on screen, which is what test frameworks’ waitFor and Playwright’s auto-waiting do, with a generous cap that is rarely used in full']],
    fin: [['고정 대기는 환경을 타요', 'fixed waits depend on the machine', 'swt-xs swt-a'], ['바쁠 때 60.5% 실패', '60.5% fail when busy'], ['조건을 기다려요', 'wait for conditions']],
    caps: [['정해진 시간 기다리기', 'Waiting a fixed time'], ['바쁜 CPU', 'A busy CPU'], ['조건 기다리기', 'Waiting for a condition'], ['어디에나 맞는 대기', 'Waits that fit anywhere'], ['sleep과 기다리기', 'Sleeping versus waiting']]
  });
}

function sRetryMaskT() {
  return CW('tst-retry-mask', {
    code: ['const b = acct.bal', 'if (Math.random() < 0.03) await sleep(0)', 'acct.bal = b + n          // lost update', ['// 진짜 경쟁 버그: 3%의 실행에서 실패', '// a real race: fails in 3% of runs'], 'retries: 2               // CI setting'],
    hl: [[0, 3, 'danger'], [3, 1, 'ink-3'], [4, 1, 'warn']],
    draw: (S) => {
      rbars(S, 'b1', .5, [[['한 번 실행', 'single run'], 5.0, 'danger', '3.02%'], [['재시도 2번', '2 retries'], .05, 'ok', '0 / 4,000']], 1);
      lbl(S, 'l1', 19.0, 1.75, ['실패율 3%인 진짜 경쟁 버그가 재시도 두 번으로 4,000번 빌드에서 한 번도 빨간불이 되지 않았어요', 'a real 3% race bug never turned a build red in 4,000 builds with two retries'], 'r', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 3.15, ['세 번 연속 실패할 확률은 0.0027%예요 · 테스트는 초록이고 버그는 운영에 남아요', 'three failures in a row has a 0.0027% chance: green tests, bug still in production'], 'w', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 4.55, ['재시도는 테스트의 불안정함과 코드의 경쟁을 구별하지 못해요', 'retries cannot tell a flaky test from racy code'], 'a', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 5.95, ['재시도로 통과한 테스트는 기록해서 따로 고쳐요', 'record tests that passed only on retry and fix them separately'], 'g', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['재시도는 진통제예요 · 치료가 아니에요', 'retries are painkillers, not cures'], 'w', 4, { w: 16.0 });
    },
    notes: [['계좌에 10원과 20원을 동시에 입금하는 테스트예요 · 입금은 잔액을 읽고, 가끔 다른 일을 기다린 뒤, 읽은 값에 더해 써요 · 첫 입금이 기다리는 사이 둘째 입금이 끝나면, 첫 입금이 옛 잔액으로 덮어써 20원이 사라져요 · 4,000번 돌리자 3.02%가 실패했어요', 'a test deposits 10 and 20 into an account concurrently, each deposit reading the balance, sometimes awaiting other work, then writing the read value plus its amount, so if the second deposit completes while the first waits, the first overwrites with the old balance and 20 vanishes, which failed 3.02% of 4,000 runs'], ['불안정한 테스트에 지친 팀은 CI에 실패하면 두 번 다시 돌리는 재시도를 걸곤 해요 · 같은 테스트를 재시도 두 번으로 4,000번 돌리자 빌드가 빨간불이 된 적은 한 번도 없었어요 · 세 번 연속 실패할 확률이 3%의 세제곱, 0.0027%이기 때문이에요', 'teams tired of flaky tests often configure CI to rerun failures twice, and running the same test with two retries 4,000 times never once turned the build red, since three failures in a row has a probability of 3% cubed, 0.0027%'], ['문제는 이 테스트가 불안정한 것이 아니라 코드가 틀렸다는 거예요 · 운영에서는 같은 경쟁이 진짜 돈을 잃게 해요 · 재시도는 테스트 쪽의 타이밍 문제와 코드 쪽의 경쟁 버그를 구별하지 못하고 둘 다 덮어요', 'the problem is that the test is not flaky, the code is wrong, and in production the same race loses real money, while retries cannot distinguish timing problems in tests from race bugs in code and cover up both'], ['재시도를 쓴다면 재시도 끝에 통과한 테스트를 기록하고, 그 목록을 불안정한 테스트로 따로 관리해 고쳐요 · 재시도 덕분에 통과한 비율이 늘면 경고를 띄워요 · 재시도는 CI를 잠시 진정시키는 진통제일 뿐 치료가 아니에요', 'when retries are used, tests that passed only after retrying are recorded and managed as a separate flaky list to be fixed, with alerts when the share passing thanks to retries grows, since retries are a painkiller that calms CI for a while, not a cure']],
    fin: [['재시도가 버그를 숨겨요', 'retries hide bugs', 'swt-xs swt-a'], ['3% → 0.0027%', '3% → 0.0027%'], ['재시도 통과를 기록해요', 'record retry passes']],
    caps: [['경쟁 버그', 'A race bug'], ['재시도의 효과', 'The effect of retries'], ['구별하지 못해요', 'It cannot tell'], ['재시도를 쓴다면', 'If retries are used'], ['재시도가 숨기는 것', 'What retries hide']]
  });
}

function sFlakyDetectT() {
  return CW('tst-flaky-detect', {
    code: [['P(한 번 이상 실패) = 1 − (1 − q)^n', 'P(at least one failure) = 1 − (1 − q)^n'], 'n = ⌈ log 0.05 / log(1 − q) ⌉', ['// 95% 확률로 한 번은 실패를 보려면?', '// how many reruns to see one failure at 95%?'], 'q = 1%  → n = 299', 'q = 5%  → n = 59'],
    hl: [[0, 2, 'accent'], [2, 1, 'ink-3'], [3, 2, 'warn']],
    draw: (S) => {
      rbars(S, 'b1', .5, [[['실패율 1%', 'q = 1%'], 5.0, 'warn', '299 runs'], [['실패율 3%', 'q = 3%'], 1.66, 'ok', '99 runs'], [['실패율 5%', 'q = 5%'], .99, 'ok', '59 runs']], 1);
      lbl(S, 'l1', 19.0, 2.3, ['95% 확률로 실패를 한 번이라도 보려면 다시 돌려야 하는 횟수예요', 'reruns needed to see at least one failure with 95% probability'], 'a', 1, { w: 12.4 });
      mono(S, 'm2', 19.0, 3.7, nbs([['2,000번 시뮬레이션에서 찾은 비율', 'detected in 2,000 simulations'], '  1%: 94.5%  3%: 95.5%  5%: 95.5%']), 2, { w: 12.4, dy: .55, c: 'swt-g' });
      lbl(S, 'l2', 19.0, 4.9, ['드물게 실패할수록 재현에 수백 번이 필요해요 · 한두 번 다시 돌려 통과했다고 고쳐진 게 아니에요', 'rarer flakes need hundreds of reruns: passing once or twice proves nothing'], 'w', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.3, ['밤마다 같은 커밋을 여러 번 돌려 결과가 섞인 테스트를 찾아요', 'rerun the same commit nightly to find tests with mixed results'], 'g', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['고쳤다고 말하려면 같은 수만큼 다시 통과해야 해요', 'claiming a fix needs the same number of clean reruns'], 'a', 4, { w: 16.0 });
    },
    notes: [['불안정한 테스트는 같은 코드에서 통과하기도 실패하기도 해요 · 실패율이 q인 테스트를 n번 돌려 한 번이라도 실패할 확률은 1 − (1 − q)^n이에요 · 이 확률이 95%가 되는 n을 계산하자 실패율 1%는 299번, 3%는 99번, 5%는 59번이었어요', 'flaky tests pass and fail on the same code, and a test with failure rate q fails at least once in n runs with probability 1 − (1 − q)^n, so solving for 95% gave 299 runs at a 1% failure rate, 99 at 3% and 59 at 5%'], ['각 횟수만큼 다시 돌리는 실험을 2,000번 시뮬레이션하자, 실패를 한 번 이상 본 비율은 1%에서 94.5%, 3%와 5%에서 95.5%로 계산과 맞았어요 · 실패율 1%인 테스트는 300번 가까이 돌려야 겨우 한 번 실패를 볼 수 있어요', 'simulating each rerun count 2,000 times, the share that saw at least one failure was 94.5% at 1% and 95.5% at 3% and 5%, matching the calculation, so a test failing 1% of the time takes nearly 300 runs just to be seen failing once'], ['그래서 실패한 테스트를 한두 번 다시 돌려 통과했다고 해서 문제가 없는 것이 아니에요 · 반대로 고쳤다고 말하려면 같은 수만큼 다시 돌려 한 번도 실패하지 않아야 해요 · 1%짜리라면 299번 연속 통과가 필요해요', 'a failing test passing on one or two reruns therefore proves nothing, and conversely, claiming a fix requires as many reruns without a single failure, 299 consecutive passes for a 1% flake'], ['많은 팀이 밤마다 같은 커밋으로 테스트를 여러 번 돌려, 결과가 섞인 테스트를 불안정한 테스트로 표시해요 · 표시된 테스트는 격리해 원인을 고치고, 고친 뒤에는 충분히 다시 돌려 확인해요', 'many teams rerun tests on the same commit several times nightly and flag those with mixed results as flaky, quarantining them while the cause is fixed and confirming the fix with enough reruns afterward']],
    fin: [['1%는 299번', '1% needs 299 runs', 'swt-xs swt-a'], ['몇 번 통과는 증거가 아니에요', 'a few passes prove nothing'], ['같은 커밋을 여러 번', 'rerun the same commit']],
    caps: [['실패할 확률', 'The chance of failing'], ['시뮬레이션', 'Simulation'], ['고쳤다는 증거', 'Evidence of a fix'], ['찾아내는 방법', 'How to find them'], ['불안정한 테스트 찾기', 'Finding flaky tests']]
  });
}

function sParallelT() {
  return CW('tst-parallel', {
    code: ['server.listen(7100)       // fixed port', ['// 워커 4개가 동시에 같은 포트를 열면?', '// 4 workers opening the same port?'], 'server.listen(0)          // OS picks a port', 'const { port } = server.address()', ['// DB도 워커마다 따로', '// a database per worker too']],
    hl: [[0, 2, 'danger'], [2, 2, 'ok'], [4, 1, 'ink-3']],
    draw: (S) => {
      rbars(S, 'b1', .5, [[['고정, 워커 1', 'fixed, 1'], .05, 'ok', '0 / 25'], [['고정, 워커 4', 'fixed, 4'], 5.0, 'danger', '75 / 100'], [['0번, 워커 4', 'port 0, 4'], .05, 'ok', '0 / 100']], 1);
      lbl(S, 'l1', 19.0, 2.3, ['혼자 돌릴 때는 통과하던 테스트가 워커 4개로 나누자 100개 중 75개 실패했어요', 'tests passing alone failed 75 of 100 when split across 4 workers'], 'r', 1, { w: 12.4 });
      T(S, 't2', 19.0, 3.7, 'EADDRINUSE: address already in use :::7100', 'cz-mono swt-tiny swt-r', 2, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.3, ['한 번에 한 워커만 그 포트를 쓸 수 있었어요', 'only one worker at a time could hold the port'], 'w', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.7, ['포트 0을 주면 운영체제가 빈 포트를 골라 줘서 실패가 0개였어요', 'port 0 lets the OS pick a free port: zero failures'], 'g', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['포트, 파일, DB, 계정은 워커마다 따로 줘요', 'give each worker its own ports, files, databases and accounts'], 'g', 4, { w: 16.0 });
    },
    notes: [['테스트를 빨리 돌리려고 병렬 워커를 늘리면 숨어 있던 공유 자원 문제가 드러나요 · 테스트마다 서버를 고정 포트 7100에 띄우고 요청한 뒤 닫는 테스트 25개를 만들었어요 · 워커 하나로 돌리자 25개 모두 통과했어요', 'adding parallel workers to speed up tests exposes hidden shared-resource problems, so 25 tests each started a server on the fixed port 7100, sent a request and closed it, all passing with a single worker'], ['같은 테스트를 워커 4개에서 동시에 돌리자 100개 중 75개가 EADDRINUSE 오류로 실패했어요 · 한 포트는 한 번에 한 프로세스만 열 수 있으므로, 사실상 한 워커만 성공하고 나머지는 모두 실패한 거예요', 'running the same tests on four workers at once failed 75 of 100 with EADDRINUSE, since only one process can hold a port at a time, so effectively one worker succeeded and the rest failed'], ['listen에 포트 0을 주면 운영체제가 비어 있는 포트를 골라 주고, server.address()로 그 번호를 알 수 있어요 · 이렇게 바꾸자 워커 4개에서도 100개 모두 통과했어요 · 시간도 거의 같았어요', 'passing port 0 to listen makes the operating system choose a free port, readable via server.address(), and with this change all 100 passed on four workers in about the same time'], ['포트만의 문제가 아니에요 · 같은 임시 파일 경로, 같은 DB의 같은 행, 같은 테스트 계정, 같은 캐시 키를 여러 워커가 함께 쓰면 똑같이 부딪쳐요 · 워커 번호를 이용해 자원 이름을 다르게 만들거나 워커마다 DB를 따로 줘요', 'the problem is not limited to ports: the same temp file path, the same row of the same database, the same test account or the same cache key shared by several workers collide just the same, so resource names are made distinct using the worker number, or each worker gets its own database']],
    fin: [['공유 자원이 부딪쳐요', 'shared resources collide', 'swt-xs swt-a'], ['워커 4개에 75% 실패', '75% fail on 4 workers'], ['포트 0으로 0개', 'port 0: zero failures']],
    caps: [['고정 포트', 'A fixed port'], ['병렬의 충돌', 'Parallel collisions'], ['운영체제가 고른 포트', 'An OS-chosen port'], ['다른 공유 자원', 'Other shared resources'], ['병렬 실행의 충돌', 'Conflicts in parallel runs']]
  });
}

function sUnawaitedT() {
  return CW('tst-unawaited', {
    code: ["test('A: saves', () => {", '  save(-1)                 // forgot await', '  expect(true).toBe(true) })', ['// save는 50ms 뒤에 예외를 던져요', '// save throws 50 ms later'], "test('B: unrelated', async () => { … })"],
    hl: [[0, 3, 'danger'], [3, 1, 'ink-3'], [4, 1, 'ink-3']],
    draw: (S) => {
      mono(S, 'm1', 19.0, .5, nbs(['vitest:  Tests 2 passed (2)', '         Errors 1 error', '         Unhandled Rejection', '         exit code 1']), 1, { w: 12.4, dy: .55, c: 'swt-w' });
      lbl(S, 'l1', 19.0, 2.85, ['Vitest는 두 테스트를 모두 통과로 세고, 오류를 파일 단위로만 알렸어요', 'Vitest counted both tests as passed and reported the error per file only'], 'w', 1, { w: 12.4 });
      mono(S, 'm2', 19.0, 4.25, nbs(['node:test: ok 1 A, ok 2 B', '  A generated asynchronous activity', '  after the test ended · fail 1']), 2, { w: 12.4, dy: .55, c: 'swt-g' });
      lbl(S, 'l2', 19.0, 5.95, ['node:test는 원인이 된 테스트 A의 이름을 짚었어요', 'node:test named test A as the source'], 'g', 2, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['둘 다 실행을 실패로 끝냈어요 · 그 오류를 무시하면 안 돼요', 'both ended the run as failed: never ignore those errors'], 'a', 3, { w: 16.0 });
    },
    notes: [['테스트 A는 저장 함수를 부르면서 await를 빠뜨렸어요 · 저장 함수는 50ms 뒤 음수 금액이라며 예외를 던지지만, 테스트 A는 그 전에 이미 끝나 통과해요 · 같은 파일의 테스트 B는 100ms를 기다리는 관계없는 테스트예요', 'test A calls a save function but forgets await, and although save throws 50 ms later complaining about a negative amount, test A has already finished and passed by then, while test B in the same file is an unrelated test waiting 100 ms'], ['Vitest로 돌리자 Tests 2 passed와 함께 Errors 1 error, Unhandled Rejection이 보고됐어요 · 오류가 이 파일을 실행하는 동안 생겼지만 파일 안에서 던져졌다는 뜻은 아니라는 안내가 붙었고, 어느 테스트의 오류인지는 알려 주지 않았어요 · 종료 코드는 1이었어요', 'running it with Vitest reported Tests 2 passed together with Errors 1 error and an Unhandled Rejection, noting that the error originated while this file was running without implying it was thrown inside the file, without naming which test, and with exit code 1'], ['node:test는 두 테스트를 ok로 표시한 뒤, 테스트 A가 끝난 뒤에 비동기 활동을 일으켰고 그 활동이 오류를 만들었다고 이름을 짚어 알렸어요 · 파일은 실패로 처리되어 pass 2, fail 1이 됐고 종료 코드는 1이었어요', 'node:test marked both tests ok, then reported by name that test A generated asynchronous activity after it ended which produced the error, failing the file with pass 2, fail 1 and exit code 1'], ['await를 빠뜨린 테스트는 확인해야 할 실패를 놓치고, 그 실패가 다른 테스트가 도는 중에 터져 엉뚱한 테스트를 의심하게 만들어요 · 린터의 no-floating-promises 규칙으로 기다리지 않은 Promise를 찾고, 처리되지 않은 거절을 테스트 실패로 다루는 설정을 꺼 두지 않아요', 'a test missing await misses the failure it should check, and that failure fires while another test is running, casting suspicion on the wrong test, so a linter’s no-floating-promises rule finds unawaited promises and the setting treating unhandled rejections as failures is never turned off']],
    fin: [['await를 빠뜨리면', 'when await is missing', 'swt-xs swt-a'], ['통과로 세고 오류는 따로', 'counted as passed, error apart'], ['린터로 미리 막아요', 'stop it with a linter']],
    caps: [['await 없는 호출', 'A call without await'], ['Vitest의 보고', 'Vitest’s report'], ['node:test의 보고', 'node:test’s report'], ['미리 막기', 'Preventing it'], ['기다리지 않은 Promise', 'Unawaited promises']]
  });
}
