      lbl(S, 'l1', 19.0, 2.85, ['150ms를 기다리고 누르자 24%는 아직 비활성 버튼을 눌러 아무 일도 없었어요', 'clicking after 150 ms hit a still-disabled button 24% of the time'], 'r', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.25, ['350ms로 늘리면 통과하지만 테스트마다 시간을 버렸어요', 'raising it to 350 ms passed but wasted time on every test'], 'w', 2, { w: 12.4 });
