      lbl(S, 'l2', 19.0, 3.75, ['순서대로 나누면 느린 파일이 두 샤드에 몰려 10.42초, 시간 기준으로 나누면 6.71초였어요', 'in order, slow files bunched into two shards (10.42 s); by duration, 6.71 s'], 'g', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.15, ['CI 전체 시간은 가장 늦게 끝나는 샤드가 정해요', 'CI time is set by the slowest shard'], 'a', 3, { w: 12.4 });
