function sFuzzT() {
  return CW('tst-fuzz', {
    code: ["if data[0] == ord('F'):", "  if data[1] == ord('U'):", "    if data[2] == ord('Z'):", "      if data[3] == ord('Z'): crash()", 'atheris.Setup(sys.argv, one); atheris.Fuzz()'],
    hl: [[0, 4, 'danger'], [4, 1, 'accent']],
    draw: (S) => {
      mono(S, 'm1', 19.0, .5, nbs([['무작위 입력 200만 개: 0번', '2M random inputs: 0 hits'], ['  입력 하나의 확률 2.3 × 10⁻¹⁰', '  chance per input 2.3 × 10⁻¹⁰'], ['atheris 시드 1: ~20,506번, 116ms', 'atheris seed 1: ~20,506 runs, 116 ms'], ['        시드 2: ~121,853번, 259ms', '        seed 2: ~121,853 runs, 259 ms'], ['        시드 3: ~15,323번, 108ms', '        seed 3: ~15,323 runs, 108 ms']]), 1, { w: 12.4, dy: .55, c: 'swt-g' });
      lbl(S, 'l1', 19.0, 3.4, ['무작위로는 40억 번에 한 번 맞는 조건을, 커버리지를 따라가는 퍼저는 0.3초 안에 찾았어요', 'a 1-in-4-billion condition: the coverage-guided fuzzer found it in 0.3 s'], 'g', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.8, ['새 분기에 닿은 입력을 모아 두고, 비교하는 값을 사전으로 써서 한 글자씩 맞춰 갔어요', 'it kept inputs reaching new branches and used compared values as a dictionary'], 'a', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.2, ['찾은 입력은 crash 파일로 저장돼 그대로 회귀 테스트가 돼요', 'the found input is saved as a crash file and becomes a regression test'], 'g', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['파서, 디코더처럼 바깥 입력을 받는 코드에 써요', 'use it on code taking outside input, such as parsers and decoders'], 'a', 4, { w: 16.0 });
    },
    notes: [['퍼징은 프로그램에 수많은 입력을 넣어 오류를 찾아요 · 첫 네 바이트가 FUZZ일 때만 오류가 나는 함수를 만들었어요 · 무작위 바이트로 맞힐 확률은 입력 하나에 2.3 × 10⁻¹⁰, 약 40억 분의 1이에요 · 무작위 8바이트 입력 200만 개를 넣자 한 번도 맞히지 못했어요', 'fuzzing feeds programs huge numbers of inputs to find errors, so a function failing only when its first four bytes are FUZZ was written, a chance of 2.3 × 10⁻¹⁰ per random input, about one in four billion, and two million random 8-byte inputs never hit it'], ['파이썬용 퍼저 atheris는 LLVM의 libFuzzer를 바탕으로 해요 · 실행 중에 코드의 어느 분기를 지났는지 기록하고, 새 분기에 닿은 입력을 모아 두었다가 조금씩 바꿔 다시 넣어요 · F를 맞힌 입력이 생기면 그것을 바탕으로 U를 찾고, 그다음 Z를 찾는 식으로 한 글자씩 나아가요', 'atheris, a fuzzer for Python, builds on LLVM’s libFuzzer, recording which branches each run passes, keeping inputs that reach new branches and mutating them slightly to try again, so once an input matches F it builds on that to find U, then Z, advancing one character at a time'], ['시드 세 개로 돌리자 약 2만 번, 12만 번, 1만 5천 번의 실행 만에 오류를 찾았고 시간은 0.1에서 0.26초였어요 · 로그에는 커버리지가 8에서 10으로 늘어난 기록과, 비교에 쓰인 값을 사전으로 삼은 CMP 변이가 보였어요', 'with three seeds it found the error after about 20,000, 120,000 and 15,000 runs, in 0.1 to 0.26 seconds, the log showing coverage rising from 8 to 10 and CMP mutations that used values from comparisons as a dictionary'], ['찾은 입력은 crash로 시작하는 파일로 저장돼요 · 이 파일을 테스트에 넣으면 같은 버그가 다시 생기지 않는지 확인하는 회귀 테스트가 돼요 · 퍼징은 파서, 디코더, 이미지와 압축 처리처럼 믿을 수 없는 바깥 입력을 받는 코드에서 특히 많은 버그를 찾아요', 'the found input is saved to a file named starting with crash, and adding it to the tests makes a regression test confirming the bug does not return, fuzzing finding especially many bugs in code taking untrusted outside input, such as parsers, decoders and image or compression handling']],
    fin: [['커버리지를 따라가요', 'follow the coverage', 'swt-xs swt-a'], ['40억 분의 1을 0.3초에', '1 in 4 billion in 0.3 s'], ['찾은 입력은 회귀 테스트로', 'findings become regression tests']],
    caps: [['숨은 조건', 'A hidden condition'], ['커버리지 안내', 'Coverage guidance'], ['찾기까지', 'Until found'], ['찾은 뒤', 'After finding'], ['퍼징', 'Fuzzing']]
  });
}

function sModelT() {
  return CW('tst-model', {
    code: ['class LRU { put(k, v) {', '  if (this.m.size >= this.cap) evictOldest()', '  /* bug: evicts even when k exists */ … } }', 'fc.modelRun(() => ({ model, real }), cmds)', ['// 명령: put(k, v), get(k) · 모델과 비교', '// commands: put, get · compared to a model']],
    hl: [[0, 3, 'danger'], [3, 2, 'accent']],
    draw: (S) => {
      mono(S, 'm1', 19.0, .5, nbs([['찾은 시도: 29, 27, 54, 68번째', 'found at runs 29, 27, 54, 68'], ['처음 실패한 명령 10~15개', 'first failing: 10–15 commands'], ['→ 축소 6~10번', '→ shrunk in 6–10 steps']]), 1, { w: 12.4, dy: .55, c: 'swt-g' });
      T(S, 't2', 19.0, 2.4, 'put(c),put(a),put(d),put(a),get(c)', 'cz-mono swt-tiny swt-r', 2, { w: 12.4 });
      lbl(S, 'l2', 19.0, 3.0, ['용량 3에서 있는 키 a를 다시 넣자 c가 쫓겨나 get(c)가 모델과 달랐어요', 'at capacity 3, re-putting existing key a evicted c, so get(c) differed from the model'], 'r', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 4.4, ['단순하지만 확실한 모델과 진짜 구현에 같은 명령을 보내 결과를 비교했어요', 'the same commands went to a simple trusted model and the real implementation'], 'a', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 5.8, ['사람이 생각하기 어려운 순서를 찾아 다섯 단계짜리 재현 방법으로 줄여 줘요', 'it finds orderings people miss and shrinks them to a five-step reproduction'], 'g', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['캐시, 큐, 상태 기계처럼 상태가 있는 코드에 잘 맞아요', 'well suited to stateful code: caches, queues, state machines'], 'a', 4, { w: 16.0 });
    },
    notes: [['상태가 있는 코드의 버그는 특정한 명령의 순서에서만 나타나요 · 용량이 정해진 LRU 캐시를 만들고, 가득 찼을 때 이미 있는 키를 다시 넣어도 가장 오래된 항목을 쫓아내는 버그를 넣었어요 · 있는 키를 갱신할 때는 아무것도 쫓아내면 안 돼요', 'bugs in stateful code appear only in particular orderings of operations, so an LRU cache with fixed capacity was built with a bug evicting the oldest entry even when re-putting a key that already exists, where updating an existing key should evict nothing'], ['모델 기반 테스트는 느리지만 확실한 모델을 하나 더 만들어요 · 배열로 순서를 관리하는 단순한 캐시예요 · fast-check가 put과 get을 무작위로 섞은 명령 순서를 만들어 모델과 진짜 캐시에 똑같이 보내고, get의 결과가 다르면 실패로 봐요', 'model-based testing builds a second, slow but trustworthy model, here a simple cache tracking order in an array, and fast-check generates random sequences of put and get commands, sends them to both the model and the real cache, and treats any differing get result as failure'], ['시드 네 개로 돌리자 29, 27, 54, 68번째 시도에서 실패를 찾았어요 · 처음 실패한 순서는 명령 10에서 15개였지만, 축소 6에서 10번 만에 put(c), put(a), put(d), put(a), get(c)처럼 다섯 개로 줄었어요', 'with four seeds it found failures at runs 29, 27, 54 and 68, the first failing sequences having 10 to 15 commands but shrinking in 6 to 10 steps to five, such as put(c), put(a), put(d), put(a), get(c)'], ['용량 3을 c, a, d로 채운 뒤 있는 키 a를 다시 넣자 c가 쫓겨나, 모델에는 있는 c가 진짜 캐시에는 없었어요 · 사람이 예시 테스트로 떠올리기 어려운 순서예요 · 캐시, 큐, 은행 계좌, 상태 기계처럼 상태가 있는 코드에 잘 맞고, 모델이 단순할수록 믿을 수 있어요', 'after filling capacity 3 with c, a and d, re-putting the existing key a evicted c, so c was in the model but missing from the real cache, an ordering people rarely think of in example tests, and the approach suits stateful code such as caches, queues, bank accounts and state machines, the model being more trustworthy the simpler it is']],
    fin: [['모델과 비교해요', 'compare to a model', 'swt-xs swt-a'], ['15개 → 5개 명령', '15 → 5 commands'], ['상태 있는 코드에', 'for stateful code']],
    caps: [['순서의 버그', 'Ordering bugs'], ['모델', 'The model'], ['찾고 줄이기', 'Finding and shrinking'], ['드러난 원인', 'The cause revealed'], ['모델 기반 테스트', 'Model-based testing']]
  });
}

